/// <summary>
/// Example GUPPricingAttribute of table <c>InventDim</c> field InventLocationId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimInventLocationId_Product extends GUPPricingAttributeInventDim_Product implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventLocationId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventLocationId from inventDim
        group by InventLocationId
    {
        ret.add(inventDim.InventLocationId);
    }
    return ret;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(InventDim, InventLocationId));
        qbr.value(queryValue(_value));
    }
